definition.script:
var dateInput = input.get('datetime');
var fromTz = input.get('fromTimezone') || 'UTC';
var toTz = input.get('toTimezone') || 'UTC';
var outputFormat = input.get('format') || 'ISO';

function parseOffset(tz) {
    if (tz === 'UTC' || tz === 'GMT') return 0;
    var match = tz.match(/^UTC([+-])(\d{1,2})(?::(\d{2}))?$/);
    if (match) {
        var sign = match[1] === '+' ? 1 : -1;
        var hours = parseInt(match[2]);
        var mins = parseInt(match[3] || '0');
        return sign * (hours * 60 + mins);
    }
    var zones = {
        'EST': -300, 'EDT': -240, 'CST': -360, 'CDT': -300,
        'MST': -420, 'MDT': -360, 'PST': -480, 'PDT': -420,
        'GMT': 0, 'BST': 60, 'CET': 60, 'CEST': 120,
        'EET': 120, 'EEST': 180, 'IST': 330, 'JST': 540,
        'AEST': 600, 'AEDT': 660, 'NZST': 720, 'NZDT': 780
    };
    if (zones[tz.toUpperCase()] !== undefined) return zones[tz.toUpperCase()];
    throw new Error('Unknown timezone: ' + tz);
}

if (!dateInput) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Datetime input is required');
    tags.trigger('error');
} else {
    try {
        var date = new Date(dateInput);
        if (isNaN(date.getTime())) throw new Error('Invalid datetime format');

        var fromOffset = parseOffset(fromTz);
        var toOffset = parseOffset(toTz);

        var utcMs = date.getTime() - (fromOffset * 60 * 1000);
        var targetMs = utcMs + (toOffset * 60 * 1000);
        var targetDate = new Date(targetMs);

        function pad(n) { return n < 10 ? '0' + n : n; }

        var y = targetDate.getUTCFullYear();
        var m = pad(targetDate.getUTCMonth() + 1);
        var d = pad(targetDate.getUTCDate());
        var h = pad(targetDate.getUTCHours());
        var min = pad(targetDate.getUTCMinutes());
        var s = pad(targetDate.getUTCSeconds());

        var result;
        var offsetStr = (toOffset >= 0 ? '+' : '-') + pad(Math.floor(Math.abs(toOffset) / 60)) + ':' + pad(Math.abs(toOffset) % 60);

        switch (outputFormat) {
            case 'ISO':
                result = y + '-' + m + '-' + d + 'T' + h + ':' + min + ':' + s + offsetStr;
                break;
            case 'DateTime':
                result = y + '-' + m + '-' + d + ' ' + h + ':' + min + ':' + s;
                break;
            case 'DateOnly':
                result = y + '-' + m + '-' + d;
                break;
            case 'TimeOnly':
                result = h + ':' + min + ':' + s;
                break;
            default:
                result = y + '-' + m + '-' + d + 'T' + h + ':' + min + ':' + s + offsetStr;
        }

        var diffMins = toOffset - fromOffset;
        var diffHrs = diffMins / 60;
        var diffStr = (diffMins >= 0 ? '+' : '') + diffHrs + ' hours';

        output.set('Result', result);
        output.set('UTC', new Date(utcMs).toISOString());
        output.set('Year', y);
        output.set('Month', targetDate.getUTCMonth() + 1);
        output.set('Day', targetDate.getUTCDate());
        output.set('Hour', targetDate.getUTCHours());
        output.set('Minute', targetDate.getUTCMinutes());
        output.set('Second', targetDate.getUTCSeconds());
        output.set('Offset', offsetStr);
        output.set('OffsetMinutes', toOffset);
        output.set('TimeDifference', diffStr);
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Converted: ' + fromTz + ' -> ' + toTz + ' = ' + result);
        tags.trigger('success');

    } catch (ex) {
        log.error('Timezone conversion failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        tags.trigger('error');
    }
}
